# Fixed by Regent iac-guardian — reviewed by CloudGuard-IaC before the PR was opened.

terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "eu-west-3"
}

variable "corporate_cidrs" {
  description = "CIDR ranges allowed to reach the bastion over SSH."
  type        = list(string)
}

variable "kms_key_arn" {
  description = "KMS key used to encrypt the uploads bucket."
  type        = string
}

resource "aws_s3_bucket" "uploads" {
  bucket = "acme-demo-uploads"
}

resource "aws_s3_bucket_public_access_block" "uploads" {
  bucket                  = aws_s3_bucket.uploads.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "uploads" {
  bucket = aws_s3_bucket.uploads.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.kms_key_arn
    }
  }
}

resource "aws_s3_bucket_versioning" "uploads" {
  bucket = aws_s3_bucket.uploads.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_security_group" "bastion" {
  name        = "bastion"
  description = "SSH from the corporate ranges only"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.corporate_cidrs
  }
}
